const recipe_run = $input.first().json.previous_state;
const output = $input.first().json.output;

// 1. Copy the keys of recipe_run
const originalKeys = Object.keys(recipe_run);

// 2. Create a new object for the updated keys and values
const updatedRecipeRun = {};

// 3. Iterate through the original keys to store the order
originalKeys.forEach(key => {
  if (key in output) {
    // if the key is in the output, we check its type
    const originalValue = recipe_run[key];
    const newValue = output[key];

    if (originalValue !== null && typeof originalValue === 'object' && !Array.isArray(originalValue) && typeof newValue === 'object' && newValue !== null) {
      // If it is an object, we store the order of the inner keys
      const subKeys = Object.keys(originalValue);
      const orderedSubObject = {};
      subKeys.forEach(subKey => {
        if (subKey in newValue) {
          orderedSubObject[subKey] = newValue[subKey];
        } else {
          orderedSubObject[subKey] = originalValue[subKey];
        }
      });
      // If the output contains new keys, we add them at the end
      Object.keys(newValue).forEach(subKey => {
        if (!(subKey in orderedSubObject)) {
          orderedSubObject[subKey] = newValue[subKey];
        }
      });
      updatedRecipeRun[key] = orderedSubObject;
    } else {
      // If the key is a simple value, then we overwrite it
      updatedRecipeRun[key] = newValue;
    }
  } else {
    // If the key is not in output, then we don´t edit
    updatedRecipeRun[key] = recipe_run[key];
  }
});

return {
  recipe_run: updatedRecipeRun
};
